ALTER TABLE public.seo_landing_pages ADD COLUMN IF NOT EXISTS page_kind text NOT NULL DEFAULT 'dish';
ALTER TABLE public.seo_landing_pages ADD COLUMN IF NOT EXISTS cuisine text;
ALTER TABLE public.seo_landing_pages ADD COLUMN IF NOT EXISTS ambience text;
DO $$ BEGIN ALTER TABLE public.seo_landing_pages ADD CONSTRAINT seo_landing_pages_kind_check CHECK (page_kind IN ('dish', 'cuisine', 'ambience')); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE INDEX IF NOT EXISTS seo_landing_pages_city_kind ON public.seo_landing_pages (city_id, page_kind) WHERE is_active;
CREATE OR REPLACE FUNCTION public.ambience_labels(p_ambience text) RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT CASE p_ambience WHEN 'romantisch' THEN ARRAY['Romantisch', 'Intiem'] ELSE ARRAY[]::text[] END $$;
CREATE OR REPLACE FUNCTION public.restaurant_paid_tag(p_restaurant uuid, p_category text, p_value text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.restaurant_tag_subscriptions s WHERE s.restaurant_id = p_restaurant AND s.is_active AND s.tag_category = p_category AND s.tag_value = p_value) $$;
CREATE OR REPLACE FUNCTION public.restaurant_has_cuisine(p_restaurant uuid, p_cuisines text[], p_cuisine text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT (p_cuisine = ANY (coalesce(p_cuisines, ARRAY[]::text[])) AND NOT public.restaurant_paid_tag(p_restaurant, 'cuisine', p_cuisine)) OR (SELECT count(DISTINCT rd.dish_id) FROM public.restaurant_dishes rd JOIN public.dishes dd ON dd.id = rd.dish_id WHERE rd.restaurant_id = p_restaurant AND rd.status IN ('approved_by_admin', 'verified_by_owner') AND EXISTS (SELECT 1 FROM public.cuisine_dishes cd WHERE cd.cuisine = p_cuisine AND cd.dish_slug IN (coalesce(dd.canonical_slug, dd.slug), dd.dish_group))) >= 3 $$;
CREATE OR REPLACE FUNCTION public.page_restaurant_ids(p_page_slug text) RETURNS TABLE (restaurant_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ WITH pg AS (SELECT p.page_kind, p.city_id, p.cuisine, p.ambience, coalesce(d.canonical_slug, d.slug) AS canon, coalesce(coalesce(d.canonical_slug, d.slug) = d.dish_group, false) AS is_hub FROM public.seo_landing_pages p LEFT JOIN public.dishes d ON d.id = p.dish_id WHERE p.slug = p_page_slug AND p.city_id IS NOT NULL LIMIT 1) SELECT DISTINCT rs.id FROM pg JOIN public.restaurants rs ON rs.city_id = pg.city_id AND rs.is_active WHERE (pg.page_kind = 'dish' AND EXISTS (SELECT 1 FROM public.restaurant_dishes rd JOIN public.dishes dd ON dd.id = rd.dish_id WHERE rd.restaurant_id = rs.id AND rd.status IN ('approved_by_admin', 'verified_by_owner') AND ((pg.is_hub AND dd.dish_group = pg.canon) OR (NOT pg.is_hub AND dd.canonical_slug = pg.canon)))) OR (pg.page_kind = 'cuisine' AND public.restaurant_has_cuisine(rs.id, rs.cuisines, pg.cuisine)) OR (pg.page_kind = 'ambience' AND EXISTS (SELECT 1 FROM unnest(coalesce(rs.ambience_tags, ARRAY[]::text[])) t WHERE t = ANY (public.ambience_labels(pg.ambience)) AND NOT public.restaurant_paid_tag(rs.id, 'ambience', t))) $$;
GRANT EXECUTE ON FUNCTION public.page_restaurant_ids(text) TO anon, authenticated, service_role;
CREATE TABLE IF NOT EXISTS public.landing_page_counts (page_slug text PRIMARY KEY, restaurant_count int NOT NULL, refreshed_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.landing_page_counts TO anon, authenticated;
GRANT ALL ON public.landing_page_counts TO service_role;
ALTER TABLE public.landing_page_counts ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Anyone can read landing page counts" ON public.landing_page_counts;
CREATE POLICY "Anyone can read landing page counts" ON public.landing_page_counts FOR SELECT USING (true);
CREATE OR REPLACE FUNCTION public.landing_page_restaurant_count(p_page_slug text) RETURNS int LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT coalesce((SELECT c.restaurant_count FROM public.landing_page_counts c WHERE c.page_slug = p_page_slug), (SELECT count(*)::int FROM public.page_restaurant_ids(p_page_slug))) $$;
GRANT EXECUTE ON FUNCTION public.landing_page_restaurant_count(text) TO anon, authenticated, service_role;
CREATE OR REPLACE FUNCTION public.uitgelicht_min_restaurants() RETURNS int LANGUAGE sql IMMUTABLE AS $$ SELECT 10 $$;
CREATE OR REPLACE FUNCTION public.refresh_landing_pages() RETURNS int LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_city record; v_cuisine text; v_n int; v_slug text; v_added int := 0; BEGIN FOR v_city IN SELECT DISTINCT c.id, c.name, c.slug FROM public.cities c JOIN public.seo_landing_pages p ON p.city_id = c.id AND p.is_active AND p.page_kind = 'dish' WHERE c.is_active LOOP FOR v_cuisine IN SELECT DISTINCT cuisine FROM public.cuisine_dishes LOOP v_slug := lower(replace(v_cuisine, ' ', '-')) || '-' || v_city.slug; CONTINUE WHEN EXISTS (SELECT 1 FROM public.seo_landing_pages WHERE slug = v_slug); SELECT count(*) INTO v_n FROM public.restaurants rs WHERE rs.city_id = v_city.id AND rs.is_active AND public.restaurant_has_cuisine(rs.id, rs.cuisines, v_cuisine); CONTINUE WHEN v_n < 6; INSERT INTO public.seo_landing_pages (slug, city_id, page_kind, cuisine, meta_title, meta_description, h1_title, keywords) VALUES (v_slug, v_city.id, 'cuisine', v_cuisine, v_cuisine || ' eten in ' || v_city.name || ' | Dishloopr', 'Restaurants met ' || lower(v_cuisine) || 'e gerechten op de kaart in ' || v_city.name || ', met prijzen per gerecht en beoordelingen.', v_cuisine || ' eten in ' || v_city.name, ARRAY[lower(v_cuisine) || ' ' || lower(v_city.name), lower(v_cuisine) || ' restaurant ' || lower(v_city.name)]) ON CONFLICT (slug) DO NOTHING; v_added := v_added + 1; END LOOP; v_slug := 'romantisch-uit-eten-' || v_city.slug; IF NOT EXISTS (SELECT 1 FROM public.seo_landing_pages WHERE slug = v_slug) THEN SELECT count(*) INTO v_n FROM public.restaurants rs WHERE rs.city_id = v_city.id AND rs.is_active AND EXISTS (SELECT 1 FROM unnest(coalesce(rs.ambience_tags, ARRAY[]::text[])) t WHERE t = ANY (public.ambience_labels('romantisch')) AND NOT public.restaurant_paid_tag(rs.id, 'ambience', t)); IF v_n >= 6 THEN INSERT INTO public.seo_landing_pages (slug, city_id, page_kind, ambience, meta_title, meta_description, h1_title, keywords) VALUES (v_slug, v_city.id, 'ambience', 'romantisch', 'Romantisch uit eten in ' || v_city.name || ' | Dishloopr', 'Romantische restaurants in ' || v_city.name || ', met de gerechten en prijzen van hun kaart.', 'Romantisch uit eten in ' || v_city.name, ARRAY['romantisch uit eten ' || lower(v_city.name), 'romantisch restaurant ' || lower(v_city.name)]) ON CONFLICT (slug) DO NOTHING; v_added := v_added + 1; END IF; END IF; END LOOP; INSERT INTO public.landing_page_counts (page_slug, restaurant_count, refreshed_at) SELECT p.slug, (SELECT count(*)::int FROM public.page_restaurant_ids(p.slug)), now() FROM public.seo_landing_pages p WHERE p.is_active AND p.city_id IS NOT NULL ON CONFLICT (page_slug) DO UPDATE SET restaurant_count = EXCLUDED.restaurant_count, refreshed_at = EXCLUDED.refreshed_at; RETURN v_added; END $$;
REVOKE ALL ON FUNCTION public.refresh_landing_pages() FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.refresh_landing_pages() TO service_role;
CREATE OR REPLACE FUNCTION public.uitgelicht_page_eligible(p_page_slug text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.seo_landing_pages p LEFT JOIN public.dishes d ON d.id = p.dish_id WHERE p.slug = p_page_slug AND coalesce(p.is_active, true) AND p.city_id IS NOT NULL AND (p.page_kind <> 'dish' OR EXISTS (SELECT 1 FROM public.uitgelicht_dishes u WHERE u.dish_slug = coalesce(d.canonical_slug, d.slug) AND u.enabled))) AND public.landing_page_restaurant_count(p_page_slug) >= public.uitgelicht_min_restaurants() $$;
GRANT EXECUTE ON FUNCTION public.uitgelicht_page_eligible(text) TO anon, authenticated, service_role;
CREATE OR REPLACE FUNCTION public.page_subject(p_page_slug text) RETURNS TABLE (subject text, city_name text, city_id uuid, page_kind text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT CASE p.page_kind WHEN 'cuisine' THEN p.cuisine || ' eten' WHEN 'ambience' THEN 'romantisch uit eten' ELSE lower(d.name) END, c.name, c.id, p.page_kind FROM public.seo_landing_pages p JOIN public.cities c ON c.id = p.city_id LEFT JOIN public.dishes d ON d.id = p.dish_id WHERE p.slug = p_page_slug LIMIT 1 $$;
GRANT EXECUTE ON FUNCTION public.page_subject(text) TO anon, authenticated, service_role;